import assert from 'node:assert/strict';import {readFile,writeFile} from 'node:fs/promises';import {createHash} from 'node:crypto';import path from 'node:path';import {chromium} from 'playwright';import {extract} from '../../engine/extract.mjs';import {renderedDocument} from '../../engine/form-appearance.mjs';import {revealLazyContent} from '../../engine/capture.mjs';
const root=path.resolve('work/wpf-heldout'),records=JSON.parse(await readFile(path.join(root,'heldout-form-records.json'))),browser=await chromium.launch({channel:'chrome'}),cases=[];let blockedSubmissions=0;
try{for(const record of records){assert.equal(new URL(record.url).origin,'http://127.0.0.1:9439');const shots=[];let fields;
 for(const width of [1440,390]){const page=await browser.newPage({viewport:{width,height:844},reducedMotion:'reduce'});await page.route('**/*',r=>{if(!['GET','HEAD'].includes(r.request().method())){blockedSubmissions++;return r.abort();}return new URL(r.request().url()).origin==='http://127.0.0.1:9439'?r.continue():r.abort();});assert.equal((await page.goto(record.url,{waitUntil:'networkidle'})).status(),200);await page.evaluate(()=>document.fonts.ready);await revealLazyContent(page);const model=extract(await renderedDocument(page),record.url),form=model.sourceForms.find(f=>f.provider==='wpforms');assert.ok(form);fields=form.fields;const route=new URL(record.url).pathname;
 const modern=await page.locator('.choices').count();if(route==='/workshop-interest/'){assert.equal(modern,2);assert.equal(await page.locator('select[multiple]').count(),1);}else{assert.equal(await page.locator('input[data-inputmask-mask]').count(),1);assert.ok(fields.some(f=>f.type==='textarea'));}
 const file=route.replaceAll('/','')+'-'+width+'.png';await page.screenshot({path:path.join(root,file),fullPage:true,animations:'disabled'});shots.push({width,file,modernSelects:modern});await page.close();}
 cases.push({route:new URL(record.url).pathname,definitionSHA256:createHash('sha256').update(JSON.stringify(record.definition)).digest('hex'),fields,shots});}
 assert.equal(blockedSubmissions,0);await writeFile(path.join(root,'heldout-source-check.json'),JSON.stringify({cases,sourceSubmissions:0},null,2));console.log(JSON.stringify({forms:cases.length,screenshots:cases.flatMap(c=>c.shots).length,sourceSubmissions:0}));
}finally{await browser.close();}
